import "@tanstack/react-query";

/**
 * 쿼리·뮤테이션이 실패를 "어디에" 알릴지 선언하는 자리.
 *
 * 기본 정책은 ReactQueryProvider 에 있다. 여기 있는 값은 그 기본에서 벗어나야
 * 하는 예외를 각 요청이 스스로 밝히는 수단이다. meta 로 두는 이유는 이 판단이
 * 요청을 정의한 곳(무엇을 가져오는지 아는 곳)에 있어야 하기 때문이다.
 */
declare module "@tanstack/react-query" {
  interface Register {
    queryMeta: {
      /**
       * 이 조회의 실패는 화면에 표시할 자리가 없다. 전역 토스트로 알린다.
       *
       * 조회는 대부분 화면 어딘가를 채우려고 나가므로 그 자리에서 알리는 것이
       * 맞다. 이 값이 필요한 건 눈에 보이는 자리가 없는 배경 조회뿐이다.
       */
      toastOnError?: boolean;
      /**
       * 실패해도 사용자에게 알리지 않는다.
       *
       * 실패해도 화면이 성립하는 부가 정보(닉네임 중복 확인, 지갑 잔액 등).
       * 대신 그 자리에는 0 같은 그럴듯한 값 대신 "모름"이 보여야 한다.
       */
      silent?: boolean;
    };
    mutationMeta: {
      /**
       * 전역 토스트를 띄우지 않는다. 호출부가 직접 표시한다.
       *
       * 폼이 필드 밑에 메시지를 다는 경우, 모달이 자기 안에 표시하는 경우처럼
       * 더 가까운 자리가 있을 때 쓴다.
       */
      silent?: boolean;
    };
  }
}
